p=root/'app.js';s=p.read_text(encoding='utf-8');m=re.search(r'const guides=(\[.*?\]);',s,re.S);g=json.loads(m[1]);g[12]=' '.join(html.unescape(re.sub('<[^>]+>','',r[3])) for r in rows);s=s[:m.start()]+'const guides='+json.dumps(g,ensure_ascii=False)+';'+s[m.end():];p.write_text(s,encoding='utf-8')
